import{_ as o,o as n,c as s,a2 as a}from"./chunks/framework.CBVBgcDP.js";const h=JSON.parse('{"title":"LLM 基础：跟着一个 token 走完全程","description":"","frontmatter":{"title":"LLM 基础：跟着一个 token 走完全程","tags":["LLM","Transformer","Attention","KVCache","MoE","RoPE"],"date":"2026-08-16"},"headers":[],"relativePath":"ai/llm-basics/glossary.md","filePath":"ai/llm-basics/glossary.md","lastUpdated":1786875695000}'),e={name:"ai/llm-basics/glossary.md"};function r(l,t,d,i,g,p){return n(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="llm-基础-跟着一个-token-走完全程" tabindex="-1">LLM 基础：跟着一个 token 走完全程 <a class="header-anchor" href="#llm-基础-跟着一个-token-走完全程" aria-label="Permalink to &quot;LLM 基础：跟着一个 token 走完全程&quot;">​</a></h1><blockquote><p><strong>这份文档不按字母排序，按数据流排序。</strong> 每个名词只出现在它真正被用到的位置上——如果一个概念放不进下面这条链，它就不属于本文。</p><p>每个条目固定三行：<strong>是什么</strong> / <strong>一个可验证的数字</strong> / <strong>没有它会坏在哪</strong>。第三行才是理解的地方，前两行只是记忆。</p><p>🔗 相关：<a href="/blog/ai/agent/yao-2023-react.html">ReAct 论文笔记</a></p></blockquote><hr><h2 id="_0-骨架" tabindex="-1">0. 骨架 <a class="header-anchor" href="#_0-骨架" aria-label="Permalink to &quot;0. 骨架&quot;">​</a></h2><p>先看全貌。下面 12 行是一个现代 decoder-only LLM 的<strong>全部</strong>推理逻辑，剩下的都是细节：</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 输入：&quot;猫吃鱼&quot;</span></span>
<span class="line"><span style="color:#BABED8;">ids </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> tokenizer</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">encode</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">text</span><span style="color:#89DDFF;">)</span><span style="color:#676E95;font-style:italic;">              # → [1234, 5678, 91011]        §1</span></span>
<span class="line"><span style="color:#BABED8;">x   </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> embedding</span><span style="color:#89DDFF;">[</span><span style="color:#BABED8;">ids</span><span style="color:#89DDFF;">]</span><span style="color:#676E95;font-style:italic;">                      # → [T, d_model]  残差流起点    §1 §2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">for</span><span style="color:#BABED8;"> layer </span><span style="color:#89DDFF;font-style:italic;">in</span><span style="color:#82AAFF;"> range</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">L</span><span style="color:#89DDFF;">):</span><span style="color:#676E95;font-style:italic;">                    # L 个结构完全相同的 block      §2</span></span>
<span class="line"><span style="color:#BABED8;">    x </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> x </span><span style="color:#89DDFF;">+</span><span style="color:#82AAFF;"> attn</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">rmsnorm</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">x</span><span style="color:#89DDFF;">))</span><span style="color:#676E95;font-style:italic;">              # token 之间交换信息            §3</span></span>
<span class="line"><span style="color:#BABED8;">    x </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> x </span><span style="color:#89DDFF;">+</span><span style="color:#82AAFF;"> ffn </span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">rmsnorm</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">x</span><span style="color:#89DDFF;">))</span><span style="color:#676E95;font-style:italic;">              # 80% 的参数在这一行            §4</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">logits </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> lm_head</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">rmsnorm</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">x</span><span style="color:#89DDFF;">))</span><span style="color:#676E95;font-style:italic;">              # → [T, vocab]                 §5</span></span>
<span class="line"><span style="color:#82AAFF;">next</span><span style="color:#89DDFF;">   =</span><span style="color:#82AAFF;"> sample</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">logits</span><span style="color:#89DDFF;">[-</span><span style="color:#F78C6C;">1</span><span style="color:#89DDFF;">],</span><span style="color:#82AAFF;"> temp</span><span style="color:#89DDFF;">,</span><span style="color:#82AAFF;"> top_p</span><span style="color:#89DDFF;">)</span><span style="color:#676E95;font-style:italic;">  # 只取最后一个位置              §5</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 把这一步的 K,V 存进 cache，把 next 接到序列末尾，回到第 3 行            §6</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>三件事看完这段就该记住：</p><ol><li><strong>模型是 <code>L</code> 个相同 block 的堆叠</strong>，不是一个巨大的黑箱。看懂一层就看懂了全部。</li><li><strong>每层只做两件事</strong>：attention 混 token，FFN 存知识。</li><li><strong>生成是一个循环</strong>，每次只产出一个 token，然后把自己的输出接回输入。</li></ol><h3 id="速查表-当字典用" tabindex="-1">速查表（当字典用） <a class="header-anchor" href="#速查表-当字典用" aria-label="Permalink to &quot;速查表（当字典用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名词</th><th>在哪</th><th>名词</th><th>在哪</th></tr></thead><tbody><tr><td>Token / 分词 / Tokenizer</td><td><a href="#_1-入口-从文本到向量">§1</a></td><td>FFN / MLP / SwiGLU</td><td><a href="#_4-ffn-子层-80-的参数在这里">§4</a></td></tr><tr><td>词表 Vocabulary</td><td><a href="#_1-入口-从文本到向量">§1</a></td><td>MoE / 激活参数</td><td><a href="#_4-ffn-子层-80-的参数在这里">§4</a></td></tr><tr><td>Embedding / input_ids</td><td><a href="#_1-入口-从文本到向量">§1</a></td><td>logits / lm_head</td><td><a href="#_5-出口-从向量到-token">§5</a></td></tr><tr><td>残差流 / RMSNorm</td><td><a href="#_2-主干-残差流">§2</a></td><td>温度 / Top-p / 采样</td><td><a href="#_5-出口-从向量到-token">§5</a></td></tr><tr><td>参数 / 权重 / 模型尺寸</td><td><a href="#_2-主干-残差流">§2</a></td><td>自回归生成</td><td><a href="#_6-循环-kv-cache-与上下文">§6</a></td></tr><tr><td>Attention / QKV / 多头</td><td><a href="#_3-attention-子层">§3</a></td><td>KV Cache</td><td><a href="#_6-循环-kv-cache-与上下文">§6</a></td></tr><tr><td>GQA / MQA / MLA</td><td><a href="#_3-attention-子层">§3</a></td><td>上下文窗口 / RoPE 外推</td><td><a href="#_6-循环-kv-cache-与上下文">§6</a></td></tr><tr><td>位置编码 / RoPE</td><td><a href="#_3-attention-子层">§3</a></td><td>Prefill / Decode / TTFT</td><td><a href="#_6-循环-kv-cache-与上下文">§6</a></td></tr><tr><td>Causal Mask</td><td><a href="#_3-attention-子层">§3</a></td><td>基座 / Instruct 模型</td><td><a href="#_7-权重从哪来-训练流水线">§7</a></td></tr><tr><td>预训练 / SFT / RLHF / RLVR</td><td><a href="#_7-权重从哪来-训练流水线">§7</a></td><td>Loss / 梯度 / 反向传播</td><td><a href="#_7-权重从哪来-训练流水线">§7</a></td></tr><tr><td>蒸馏 Distillation</td><td><a href="#_7-权重从哪来-训练流水线">§7</a></td><td>GPU / HBM / 量化</td><td><a href="#_8-硬件账本">§8</a></td></tr></tbody></table><hr><h2 id="_1-入口-从文本到向量" tabindex="-1">1. 入口：从文本到向量 <a class="header-anchor" href="#_1-入口-从文本到向量" aria-label="Permalink to &quot;1. 入口：从文本到向量&quot;">​</a></h2><h3 id="token-分词-tokenization" tabindex="-1">Token / 分词（Tokenization） <a class="header-anchor" href="#token-分词-tokenization" aria-label="Permalink to &quot;Token / 分词（Tokenization）&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型不吃字符，吃 token——通常是<strong>子词</strong>（subword）。英文里 <code>tokenization</code> 可能切成 <code>token|ization</code>；中文一个常用字往往就是一个 token，生僻字会被拆成多个字节 token。</li><li><strong>数字</strong>：英文约 <strong>1 token ≈ 0.75 词</strong>，中文约 <strong>1 token ≈ 1~1.5 字</strong>。算 API 成本和上下文占用都靠这个换算。</li><li><strong>没有它会坏在哪</strong>：退化到字符级建模，同一段文本的序列长度涨 <strong>4~5 倍</strong>——KV Cache（<a href="#_6-循环-kv-cache-与上下文">§6</a>）和注意力算力同比膨胀，而 attention 是 <code>O(T²)</code>。分词首先是一个<strong>压缩</strong>手段。</li></ul><h3 id="分词器-tokenizer-bpe-sentencepiece" tabindex="-1">分词器（Tokenizer：BPE / SentencePiece） <a class="header-anchor" href="#分词器-tokenizer-bpe-sentencepiece" aria-label="Permalink to &quot;分词器（Tokenizer：BPE / SentencePiece）&quot;">​</a></h3><ul><li><strong>是什么</strong>：执行分词的算法。主流是 <strong>BPE</strong>（byte-level，从字节开始反复合并高频对）；SentencePiece 是它的一种工程封装。关键性质：<strong>byte-level 意味着任何字节串都能被编码，永远不会 OOV</strong>。</li><li><strong>数字</strong>：Tokenizer 是<strong>独立训练</strong>的，且训完就冻结。换 tokenizer 等于换词表，等于整个 embedding 矩阵作废、必须重训。</li><li><strong>没有它会坏在哪</strong>：这一层的怪癖会一路渗透到模型行为。经典案例：数字被切得乱七八糟（<code>1234</code> 可能是 <code>12|34</code>），所以 LLM 做算术天生吃亏；<code>SolidGoldMagikarp</code> 这类词表里存在但训练时几乎没出现的 token，会触发彻底失控的输出。<strong>很多看起来像&quot;模型笨&quot;的现象，根因在 tokenizer。</strong></li></ul><h3 id="词表-vocabulary" tabindex="-1">词表（Vocabulary） <a class="header-anchor" href="#词表-vocabulary" aria-label="Permalink to &quot;词表（Vocabulary）&quot;">​</a></h3><ul><li><p><strong>是什么</strong>：模型认识的全部 token 的集合。生成时&quot;下一个词&quot;只能从这张表里选。</p></li><li><p><strong>数字</strong>：<strong>现在是 10 万~26 万，不是&quot;几万&quot;。</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>vocab_size</th></tr></thead><tbody><tr><td>Llama 2 / Mistral（旧世代）</td><td>32,000</td></tr><tr><td>GPT-4（cl100k）</td><td>100,256</td></tr><tr><td>Llama 3 / 3.1</td><td>128,256</td></tr><tr><td>DeepSeek V3 / R1</td><td>129,280</td></tr><tr><td>Qwen3</td><td>151,936</td></tr><tr><td>GPT-4o / o1 / o3（o200k）</td><td>~200,000</td></tr><tr><td>Llama 4 Scout</td><td>202,048</td></tr><tr><td>Gemma 3</td><td>262,208</td></tr></tbody></table></li><li><p><strong>没有它会坏在哪</strong>：词表大小是一个<strong>真实的成本项</strong>，不是无关参数。它同时决定 embedding 矩阵和 lm_head 的宽度：Gemma 3 27B 光 embedding 就 <strong>417M 参数</strong>。词表变大 → 序列变短（省算力）但矩阵变宽（费显存），是一个权衡而非免费改进。</p></li></ul><h3 id="embedding-词嵌入-input-ids" tabindex="-1">Embedding（词嵌入）/ input_ids <a class="header-anchor" href="#embedding-词嵌入-input-ids" aria-label="Permalink to &quot;Embedding（词嵌入）/ input_ids&quot;">​</a></h3><ul><li><strong>是什么</strong>：<code>input_ids</code> 是 token 在词表里的整数下标；embedding 是一张 <code>[vocab, d_model]</code> 的查找表，把下标换成向量。<strong>注意这是查表，不是矩阵乘。</strong></li><li><strong>数字</strong>：<code>d_model</code>（隐藏维度）现在典型 2048~8192。Llama 3 70B 是 8192。</li><li><strong>没有它会坏在哪</strong>：不查表就得直接拿整数进网络，那样 id=1234 和 id=1235 在数值上相邻——而词表里相邻的两个 token 毫无语义关系。embedding 的作用是<strong>把&quot;任意编号&quot;变成&quot;可学习的几何位置&quot;</strong>，语义近的词向量才可能近。</li></ul><hr><h2 id="_2-主干-残差流" tabindex="-1">2. 主干：残差流 <a class="header-anchor" href="#_2-主干-残差流" aria-label="Permalink to &quot;2. 主干：残差流&quot;">​</a></h2><blockquote><p>这一节是原文档完全缺失的部分，也是最该先补的部分。不理解残差流，Transformer 就只是一堆零件。</p></blockquote><h3 id="残差流-residual-stream" tabindex="-1">残差流（Residual Stream） <a class="header-anchor" href="#残差流-residual-stream" aria-label="Permalink to &quot;残差流（Residual Stream）&quot;">​</a></h3><ul><li><strong>是什么</strong>：贯穿全模型的一条 <code>[T, d_model]</code> 的&quot;主干道&quot;。每个子层都不是<strong>替换</strong>它，而是<strong>往上加一笔</strong>：<code>x = x + sublayer(norm(x))</code>。可以把它想成一块共享白板，每一层读一遍、往上写一点。</li><li><strong>数字</strong>：Llama 3 70B 有 <strong>80 层 × 2 个子层 = 160 次读写</strong>，全都作用在同一条 8192 维的流上。</li><li><strong>没有它会坏在哪</strong>：<strong>梯度传不回去，深网络根本训不动。</strong> 加法让反向传播有一条恒等短路（<code>∂x/∂x = 1</code>），梯度可以直达第一层。ResNet 解决的就是这个问题，Transformer 继承了它。这也是为什么&quot;深&quot;是免费的——每层只需要学一个小增量。</li></ul><h3 id="rmsnorm-pre-norm" tabindex="-1">RMSNorm / Pre-Norm <a class="header-anchor" href="#rmsnorm-pre-norm" aria-label="Permalink to &quot;RMSNorm / Pre-Norm&quot;">​</a></h3><ul><li><strong>是什么</strong>：进子层之前先把向量归一化。现代模型用 <strong>RMSNorm</strong>（只除以均方根，不减均值），比 LayerNorm 少一半操作。位置在子层<strong>之前</strong>（pre-norm），不是之后。</li><li><strong>数字</strong>：<code>x / sqrt(mean(x²) + eps) * weight</code>——每层只有 <code>d_model</code> 个可学习参数，可以忽略不计。</li><li><strong>没有它会坏在哪</strong>：残差流是一路相加的，激活值会逐层放大直到溢出，或坍缩到 0。归一化把每次进子层的输入拉回可控尺度。<strong>Pre-norm 而非 post-norm 是让大模型训练稳定的关键工程细节之一</strong>——原始 2017 Transformer 用的是 post-norm，深层时不加 warmup 就发散。</li></ul><h3 id="参数-权重-模型尺寸" tabindex="-1">参数 / 权重 / 模型尺寸 <a class="header-anchor" href="#参数-权重-模型尺寸" aria-label="Permalink to &quot;参数 / 权重 / 模型尺寸&quot;">​</a></h3><ul><li><strong>是什么</strong>：<strong>权重</strong>是学出来的数字（矩阵乘的系数），<strong>偏置</strong>是加性项，<strong>参数</strong> = 两者统称。现代 LLM 里偏置基本被去掉了（Llama 系全无 bias），所以&quot;权重&quot;和&quot;参数&quot;在实践中同义。模型 = 固定架构（代码）+ 参数（数字）。</li><li><strong>数字</strong>：一个 block 的参数分布（Llama 3 70B）：<strong>attention 17.6%，FFN 82.4%</strong>。跨模型都在 <strong>16~20% / 80~84%</strong>。</li><li><strong>没有它会坏在哪</strong>：把参数当成一坨无结构的数字，就会漏掉最重要的事实——<strong>知识主要不在注意力里，在 FFN 里</strong>（<a href="#_4-ffn-子层-80-的参数在这里">§4</a>）。MoE、剪枝、LoRA 该往哪下手，全由这个分布决定。</li><li><strong>⚠️ 参数量已经不再直接代表能力</strong>：&quot;7B / 70B&quot; 这套刻度在 MoE 时代断了。DeepSeek V3 是 <strong>671B 总参 / 37B 激活</strong>。规则：<strong>激活参数预测算力和延迟，总参数预测显存</strong>。</li></ul><hr><h2 id="_3-attention-子层" tabindex="-1">3. Attention 子层 <a class="header-anchor" href="#_3-attention-子层" aria-label="Permalink to &quot;3. Attention 子层&quot;">​</a></h2><p>一层里的第一个子层。它是模型中<strong>唯一让不同位置的 token 互相看见</strong>的地方。</p><h3 id="注意力-attention-qkv" tabindex="-1">注意力（Attention）/ QKV <a class="header-anchor" href="#注意力-attention-qkv" aria-label="Permalink to &quot;注意力（Attention）/ QKV&quot;">​</a></h3><ul><li><strong>是什么</strong>：每个位置从残差流里投影出三个向量——<strong>Q</strong>（我在找什么）、<strong>K</strong>（我能提供什么）、<strong>V</strong>（我实际携带的内容）。用 <code>Q·Kᵀ</code> 算出每个位置对其他位置的关注权重，softmax 归一化，再对 <strong>V</strong> 加权求和写回残差流。四个矩阵：<code>W_q, W_k, W_v, W_o</code>。</li><li><strong>数字</strong>：<code>softmax(Q Kᵀ / sqrt(head_dim)) V</code>。那个 <code>sqrt(head_dim)</code> 不是装饰——不除，点积方差随维度线性增长，softmax 会饱和成 one-hot，梯度消失。</li><li><strong>没有它会坏在哪</strong>：没有 attention，每个位置就是独立的，模型退化成对每个 token 单独做变换的 MLP，无法利用上下文。<strong>这是&quot;上下文&quot;这个词的物理来源。</strong></li></ul><h3 id="causal-mask-因果掩码" tabindex="-1">Causal Mask（因果掩码） <a class="header-anchor" href="#causal-mask-因果掩码" aria-label="Permalink to &quot;Causal Mask（因果掩码）&quot;">​</a></h3><ul><li><strong>是什么</strong>：训练时把注意力矩阵的上三角设为 <code>-inf</code>，让位置 <code>t</code> 只能看见 <code>≤ t</code> 的位置。</li><li><strong>数字</strong>：一行代码，<code>scores.masked_fill_(mask, -inf)</code>。</li><li><strong>没有它会坏在哪</strong>：<strong>训练和推理会不一致。</strong> 训练时模型能看见后面的答案，学会了&quot;抄&quot;；推理时后面还不存在，直接崩。有了 mask，一次前向对 <code>T</code> 个位置同时提供 <code>T</code> 个训练信号——这是&quot;预测下一个词&quot;能高效并行训练的全部原因。</li></ul><h3 id="多头注意力-multi-head-attention" tabindex="-1">多头注意力（Multi-Head Attention） <a class="header-anchor" href="#多头注意力-multi-head-attention" aria-label="Permalink to &quot;多头注意力（Multi-Head Attention）&quot;">​</a></h3><ul><li><strong>是什么</strong>：把 attention 拆成 <code>n_heads</code> 份并行做，每份在 <code>head_dim</code> 维的子空间里，结果拼回再过 <code>W_o</code>。</li><li><strong>数字</strong>：Llama 3 70B：64 头 × 128 维。注意 <strong><code>head_dim</code> 现在常和 <code>d_model / n_heads</code> 解耦</strong>——Gemma 3 27B 是 hidden 5376、32 头、head_dim 128（32×128 = 4096 ≠ 5376）。</li><li><strong>没有它会坏在哪</strong>：单个 softmax 只能表达<strong>一种</strong>关注模式。要同时追踪句法依赖、指代、和远距离主题，需要多个独立的注意力模式并行。</li></ul><h3 id="gqa-mqa-mla-kv-压缩" tabindex="-1">GQA / MQA / MLA（KV 压缩） <a class="header-anchor" href="#gqa-mqa-mla-kv-压缩" aria-label="Permalink to &quot;GQA / MQA / MLA（KV 压缩）&quot;">​</a></h3><ul><li><p><strong>是什么</strong>：Q 用满头，但 <strong>K/V 共享更少的头</strong>。MHA（每头独立）→ GQA（几个 Q 头共享一组 KV）→ MQA（全部共享一组）→ <strong>MLA</strong>（DeepSeek：把 K/V 压成一个共享的低秩 latent 向量 + 一个单独的 RoPE key）。</p></li><li><p><strong>数字</strong>：Llama 3 全系 <code>num_key_value_heads = 8</code>。</p><table tabindex="0"><thead><tr><th>模型</th><th>Q/KV 头</th><th>每 token KV</th><th>@128k</th><th>若用 MHA</th><th>压缩</th></tr></thead><tbody><tr><td>Llama 3 8B</td><td>32 / 8</td><td>128 KiB</td><td>17.2 GB</td><td>68.7 GB</td><td>4×</td></tr><tr><td>Llama 3 70B</td><td>64 / 8</td><td>320 KiB</td><td><strong>42.9 GB</strong></td><td>343.6 GB</td><td><strong>8×</strong></td></tr><tr><td>Llama 3 405B</td><td>128 / 8</td><td>504 KiB</td><td>67.6 GB</td><td>—</td><td>16×</td></tr><tr><td>DeepSeek V3（MLA）</td><td>128 / latent</td><td><strong>68.6 KiB</strong></td><td><strong>9.2 GB</strong></td><td>—</td><td>~工程等价 GQA-2.25</td></tr></tbody></table><p>DeepSeek V3 是 671B 的模型，KV Cache 却比 70B 的 Llama 3 还小 <strong>4.7 倍</strong>。MLA 论文自己的说法是&quot;KV cache 等于 2.25 组的 GQA，但效果强于 MHA&quot;；V2 相比 MHA 版本减少 <strong>93.3%</strong> KV，生成吞吐 <strong>5.76×</strong>。</p></li><li><p><strong>没有它会坏在哪</strong>：Llama 3 70B 权重 140 GB + MHA 的 343.6 GB KV，128k 上下文在任何单机上都放不下。<strong>GQA 不是微优化，它是长上下文能被商业化服务的前提。</strong></p></li><li><p><strong>同类杠杆</strong>：<strong>滑动窗口 / 局部-全局交替</strong>。Gemma 3 用 5:1 的局部:全局比例、局部窗口 1024，把 128k 的 KV 从 66.6 GB 压到 <strong>11.2 GB</strong>（~6×）。</p></li></ul><h3 id="位置编码-rope-旋转位置编码" tabindex="-1">位置编码 / RoPE（旋转位置编码） <a class="header-anchor" href="#位置编码-rope-旋转位置编码" aria-label="Permalink to &quot;位置编码 / RoPE（旋转位置编码）&quot;">​</a></h3><ul><li><p><strong>是什么</strong>：<strong>RoPE 现在是事实标准。</strong> 它不往 embedding 上加任何东西——而是在<strong>每一层 attention 内部</strong>，对 Q 和 K 按位置做旋转。旋转的相对角度天然编码了相对距离。</p></li><li><p><strong>数字</strong>：唯一的关键超参是 <strong><code>rope_theta</code>（base frequency）</strong>，它直接决定能撑多长上下文：</p><table tabindex="0"><thead><tr><th>模型</th><th>rope_theta</th></tr></thead><tbody><tr><td>原始 Llama 2 / DeepSeek V3</td><td>10,000</td></tr><tr><td>Kimi K2</td><td>50,000</td></tr><tr><td><strong>Llama 3（从 10k 提到 500k）</strong></td><td>500,000</td></tr><tr><td>Qwen3 / Gemma 3</td><td>1,000,000</td></tr><tr><td>Qwen3-Next</td><td>10,000,000</td></tr></tbody></table></li><li><p><strong>没有它会坏在哪</strong>：<strong>不给位置信息，attention 对输入顺序是置换等变的</strong>——「猫吃鱼」和「鱼吃猫」会得到完全相同的 logits。位置编码是唯一打破这个对称性的东西。</p></li><li><p><strong>⚠️ 别用旧框架</strong>：「给每个 token 注入位置信息」描述的是 2017 年的 <strong>sinusoidal 绝对位置编码</strong>和 BERT/GPT-2 的<strong>可学习绝对位置表</strong>。两者都已淘汰，致命缺陷是<strong>没法外推超过训练时那张表的长度</strong>。RoPE 因为是相对的、且由一个 base 参数控制，才有了 YaRN 这类外推手段（<a href="#_6-循环-kv-cache-与上下文">§6</a>）。</p></li><li><p><strong>2026 趋势（值得知道名字）</strong>：<strong>部分 RoPE</strong>——只旋转一部分维度（GLM-4.6 <code>partial_rotary_factor: 0.5</code>，Qwen3-Next <code>0.25</code>），或只在一部分层用（Llama 4 的 <strong>iRoPE</strong>：每 4 层有 1 层完全不加位置编码，48 层里 12 层是 NoPE）。DeepSeek 的 MLA 本身就是部分 RoPE 设计（<code>qk_nope_head_dim=128</code> + <code>qk_rope_head_dim=64</code>）。</p></li></ul><hr><h2 id="_4-ffn-子层-80-的参数在这里" tabindex="-1">4. FFN 子层：80% 的参数在这里 <a class="header-anchor" href="#_4-ffn-子层-80-的参数在这里" aria-label="Permalink to &quot;4. FFN 子层：80% 的参数在这里&quot;">​</a></h2><blockquote><p>原文档从头到尾没提过 FFN。这是最大的漏洞——它是模型里参数量最大的模块，也是知识的存放处。</p></blockquote><h3 id="ffn-mlp-swiglu" tabindex="-1">FFN / MLP / SwiGLU <a class="header-anchor" href="#ffn-mlp-swiglu" aria-label="Permalink to &quot;FFN / MLP / SwiGLU&quot;">​</a></h3><ul><li><p><strong>是什么</strong>：一个逐位置（position-wise）的两层网络：<strong>升维 → 非线性 → 降维</strong>。它<strong>不跨 token</strong>，每个位置独立计算。现代模型用 <strong>SwiGLU</strong>，需要三个矩阵：<code>gate</code>、<code>up</code>（都是 <code>d_model → d_ff</code>）、<code>down</code>（<code>d_ff → d_model</code>），计算是 <code>down(silu(gate(x)) * up(x))</code>——那个逐元素乘就是&quot;门控&quot;。</p></li><li><p><strong>数字</strong>：<code>d_ff ≈ 3.5 × d_model</code>（Llama 3 8B：4096 → 14336）。参数占比：</p><table tabindex="0"><thead><tr><th>模型</th><th>Attention</th><th><strong>FFN</strong></th></tr></thead><tbody><tr><td>Llama 3 8B</td><td>19.2%</td><td><strong>80.8%</strong></td></tr><tr><td>Llama 3 70B</td><td>17.6%</td><td><strong>82.4%</strong></td></tr><tr><td>Qwen3-32B</td><td>19.4%</td><td><strong>80.6%</strong></td></tr><tr><td>Gemma 3 27B</td><td>16.0%</td><td><strong>84.0%</strong></td></tr><tr><td><em>Llama 2 7B（MHA，无 GQA）</em></td><td><em>33.2%</em></td><td><em>66.8%</em></td></tr></tbody></table></li><li><p><strong>没有它会坏在哪</strong>：只剩 attention 的话，模型基本是一串加权平均——线性混合加一个 softmax，几乎没有存储和加工知识的容量。<strong>&quot;巴黎是法国首都&quot;这条事实存在 FFN 的权重里，不在注意力里。</strong> 常用的心智模型：attention 负责<strong>路由信息</strong>，FFN 负责<strong>存储和计算</strong>。</p></li><li><p><strong>为什么占比比教科书还高</strong>：经典说法是 FFN 约 2/3（<code>4h</code> 的 FFN + MHA）。SwiGLU 用 3 个矩阵而非 2 个，GQA 又砍小了 K/V 投影，两个因素一起把 FFN 推到了 80%+。</p></li></ul><h3 id="moe-mixture-of-experts-激活参数" tabindex="-1">MoE（Mixture of Experts）/ 激活参数 <a class="header-anchor" href="#moe-mixture-of-experts-激活参数" aria-label="Permalink to &quot;MoE（Mixture of Experts）/ 激活参数&quot;">​</a></h3><ul><li><p><strong>是什么</strong>：把 FFN 换成 <code>N</code> 个并行的 FFN（专家），一个路由器给每个 token 只挑 top-k 个执行。<strong>MoE 只作用在 FFN 层</strong>——而 FFN 正好是 80% 的参数所在，这不是巧合。</p></li><li><p><strong>数字</strong>：<strong>前沿开源模型现在基本全是 MoE。</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>总参</th><th>激活</th><th>路由专家</th><th>top-k</th><th>共享专家</th></tr></thead><tbody><tr><td>Mixtral 8x7B（老世代）</td><td>46.7B</td><td>12.9B</td><td>8</td><td>2</td><td>0</td></tr><tr><td><strong>DeepSeek V3 / R1</strong></td><td>671B</td><td><strong>37B</strong></td><td>256</td><td>8</td><td>1</td></tr><tr><td><strong>Qwen3-235B-A22B</strong></td><td>235B</td><td><strong>22B</strong></td><td>128</td><td>8</td><td>0</td></tr><tr><td>Qwen3-Next-80B-A3B</td><td>80B</td><td><strong>3B</strong></td><td>512</td><td>10</td><td>1</td></tr><tr><td><strong>Kimi K2</strong></td><td><strong>1.04T</strong></td><td><strong>32B</strong></td><td>384</td><td>8</td><td>1</td></tr><tr><td>Llama 4 Maverick</td><td>400B</td><td><strong>17B</strong></td><td>128</td><td>1</td><td>1</td></tr><tr><td>gpt-oss-120b</td><td>117B</td><td>5.1B</td><td>128</td><td>4</td><td>0</td></tr></tbody></table></li><li><p><strong>没有它会坏在哪</strong>：想要 671B 的容量就得付 671B 的算力。MoE 把<strong>容量</strong>和<strong>算力</strong>解耦——V3 每 token 只算 37B（≈ 5.5%），但保有 671B 的知识量。</p></li><li><p><strong>⚠️ 但显存不省</strong>：671B <strong>全部</strong>都得驻留在 HBM 里，即使每步只用 37B。这是 MoE 部署最反直觉的一点。</p></li><li><p><strong>趋势方向</strong>：Llama 3（2024）是最后一个大型密集前沿模型，论文明确说选密集是&quot;为了最大化训练稳定性&quot;；一年后 Llama 4 全线转 MoE。粒度也在变细：Mixtral 的 8 专家 top-2 → 现在 256~512 专家 top-8/10 + 1 个常开的共享专家。<strong>约 35B 以下仍以密集为主</strong>（Qwen3-32B、Gemma 3 全系），因为部署简单。</p></li></ul><hr><h2 id="_5-出口-从向量到-token" tabindex="-1">5. 出口：从向量到 token <a class="header-anchor" href="#_5-出口-从向量到-token" aria-label="Permalink to &quot;5. 出口：从向量到 token&quot;">​</a></h2><h3 id="lm-head-logits" tabindex="-1">lm_head / logits <a class="header-anchor" href="#lm-head-logits" aria-label="Permalink to &quot;lm_head / logits&quot;">​</a></h3><ul><li><strong>是什么</strong>：最后一层 norm 之后，用一个 <code>[d_model, vocab]</code> 的矩阵把隐状态投影成词表上的<strong>原始分数（logits）</strong>，未归一化。softmax 之后才是概率分布。</li><li><strong>数字</strong>：输出形状 <code>[T, vocab]</code>，但生成时<strong>只用最后一行</strong>——前面 <code>T-1</code> 行在推理时是浪费的（训练时它们全都是有效信号，见 causal mask）。小模型常把 lm_head 和 embedding 共享同一份权重（tied embeddings）省显存。</li><li><strong>没有它会坏在哪</strong>：残差流是 <code>d_model</code> 维的连续向量，跟词表没有对应关系。lm_head 是唯一把它翻译回&quot;哪个 token&quot;的那一步。</li></ul><h3 id="温度-top-p-top-k-采样" tabindex="-1">温度 / Top-p / Top-k / 采样 <a class="header-anchor" href="#温度-top-p-top-k-采样" aria-label="Permalink to &quot;温度 / Top-p / Top-k / 采样&quot;">​</a></h3><ul><li><strong>是什么</strong>：<code>logits / temperature</code> → softmax → 截断 → 抽样。<strong>温度</strong>缩放分布（低 → 尖锐确定，高 → 平坦随机，<code>temp → 0</code> 等于贪心）；<strong>top-k</strong> 只留概率最高的 k 个；<strong>top-p（nucleus）</strong> 留累计概率到 p 的最小集合。<code>do_sample=False</code> 就是贪心。</li><li><strong>数字</strong>：常见默认 <code>temp=0.7, top_p=0.9</code>。注意顺序：<strong>先温度缩放，后截断</strong>。</li><li><strong>没有它会坏在哪</strong>：全贪心解码输出确定，但会陷入重复循环、文风乏味。反过来温度太高就开始胡言乱语。<strong>这一层是纯推理期的旋钮，不动一个权重</strong>——同一个模型换采样参数，表现可以差很远，很多&quot;模型不行&quot;其实是采样参数不对。</li></ul><hr><h2 id="_6-循环-kv-cache-与上下文" tabindex="-1">6. 循环：KV Cache 与上下文 <a class="header-anchor" href="#_6-循环-kv-cache-与上下文" aria-label="Permalink to &quot;6. 循环：KV Cache 与上下文&quot;">​</a></h2><h3 id="自回归生成-autoregressive-generation" tabindex="-1">自回归生成（Autoregressive Generation） <a class="header-anchor" href="#自回归生成-autoregressive-generation" aria-label="Permalink to &quot;自回归生成（Autoregressive Generation）&quot;">​</a></h3><ul><li><strong>是什么</strong>：一次一个 token，每一步都把自己刚生成的接回输入，重跑一遍前向。</li><li><strong>数字</strong>：生成 500 token = <strong>500 次完整前向</strong>，串行，无法并行。</li><li><strong>没有它会坏在哪</strong>：这是 LLM 延迟的根本来源。也是<strong>幻觉会自我放大</strong>的机制来源——一旦第 10 个 token 错了，后面 490 个都在这个错误的条件下生成，模型会努力让错误显得自洽。</li></ul><h3 id="kv-cache" tabindex="-1">KV Cache <a class="header-anchor" href="#kv-cache" aria-label="Permalink to &quot;KV Cache&quot;">​</a></h3><ul><li><p><strong>是什么</strong>：注意力只需要历史 token 的 <strong>K 和 V</strong>，而它们不随后续 token 改变。所以算一次就缓存，新 token 只算自己的 QKV 再去查缓存。</p></li><li><p><strong>数字</strong>：<strong>公式必须用 <code>num_kv_heads</code>，不是 <code>hidden_dim</code>：</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>KV bytes = 2(K,V) × num_layers × num_kv_heads × head_dim × bytes_per_elem × seq_len × batch</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>用 <code>hidden_size</code> 的话会高估整整一个 GQA 倍数（Llama 3 70B 是 8 倍）。核对一遍 Llama 3 70B：<code>2 × 80 × 8 × 128 × 2 = 327,680 B = 320 KiB/token</code>。</p></li><li><p><strong>没有它会坏在哪</strong>：每步都重算全部历史的注意力，单步 <code>O(T²)</code>，生成整段变成 <code>O(T³)</code>。KV Cache 把单步降到 <code>O(T)</code>。<strong>它是用显存换算力</strong>——这一笔交易直接把上下文长度变成了显存问题（<a href="#_8-硬件账本">§8</a>）。</p></li></ul><h3 id="prefill-vs-decode" tabindex="-1">Prefill vs Decode <a class="header-anchor" href="#prefill-vs-decode" aria-label="Permalink to &quot;Prefill vs Decode&quot;">​</a></h3><ul><li><strong>是什么</strong>：<strong>Prefill</strong> 一次性并行处理整段输入 prompt（<strong>算力受限 / compute-bound</strong>），对应首 token 延迟 <strong>TTFT</strong>。<strong>Decode</strong> 之后逐 token 生成，每步只算一个（<strong>带宽受限 / memory-bound</strong>），对应每 token 延迟 <strong>TPOT</strong>。</li><li><strong>数字</strong>：这解释了&quot;长 prompt 开头卡一下、之后稳定吐字&quot;。也解释了为什么两个阶段的优化手段完全不同——prefill 拼 FLOPS，decode 拼带宽和 batch size。</li><li><strong>没有它会坏在哪</strong>：不区分这两个阶段，就无法理解任何推理性能数据。&quot;这个模型多快&quot;这个问题本身是没定义的，得问 TTFT 还是 TPOT。</li></ul><h3 id="上下文窗口-context-window" tabindex="-1">上下文窗口（Context Window） <a class="header-anchor" href="#上下文窗口-context-window" aria-label="Permalink to &quot;上下文窗口（Context Window）&quot;">​</a></h3><ul><li><strong>是什么</strong>：模型能处理的最大 token 数（输入 + 已生成）。</li><li><strong>⚠️ 这是主要由训练决定的属性，不是由显存决定的。</strong> 原文档把它写成&quot;本质受 HBM 容量约束&quot;，这个因果颠倒了。真正决定它的是： <ol><li><strong>训练序列长度 + 长上下文续训</strong>。Llama 3 405B 从 8K 起步，<strong>分六个阶段升到 128K</strong>，烧掉约 <strong>800B token</strong> 的长上下文数据，每一阶段都要求短上下文评测不掉、needle-in-a-haystack 全对才推进。</li><li><strong><code>rope_theta</code></strong>（<a href="#_3-attention-子层">§3</a>）。</li><li><strong>外推方法</strong>：<strong>YaRN</strong>、NTK-aware scaling、位置插值。DeepSeek V3 用 YaRN <code>factor: 40</code>，把 4096 扩到 163,840；Kimi K2-Thinking 用 <code>factor: 64</code> 到 262,144。</li></ol></li><li><strong>HBM 决定的是&quot;这个窗口里你能经济地服务多长&quot;</strong>，两件事分开看。两个干净的证据：(a) 同样的权重换更大显存的机器，不用重训就能吃更长上下文；(b) Gemma 3 论文明说模型能泛化到 128K，但再往上&quot;迅速退化&quot;——那是<strong>固定硬件下的质量悬崖</strong>，是训练边界不是内存边界。</li><li><strong>第三个常被混同的概念：有效上下文</strong>。声称 128k、实际检索质量在多少 token 之后开始掉，通常远低于标称值。<strong>标称长度、可服务长度、有效长度，是三个不同的数。</strong></li></ul><hr><h2 id="_7-权重从哪来-训练流水线" tabindex="-1">7. 权重从哪来：训练流水线 <a class="header-anchor" href="#_7-权重从哪来-训练流水线" aria-label="Permalink to &quot;7. 权重从哪来：训练流水线&quot;">​</a></h2><p>前面六节讲的是<strong>权重已经存在</strong>时会发生什么。这一节讲那些数字怎么来的。</p><h3 id="推理-vs-训练" tabindex="-1">推理 vs 训练 <a class="header-anchor" href="#推理-vs-训练" aria-label="Permalink to &quot;推理 vs 训练&quot;">​</a></h3><ul><li><strong>推理（Inference）</strong>：拿固定权重跑前向，产出结果。就是 <a href="#_0-骨架">§0</a> 那 12 行。</li><li><strong>训练（Training）</strong>：跑前向 → 算 loss → 反向传播 → 更新权重。显存开销约是推理的 <strong>3~4 倍</strong>（要额外存激活值、梯度、优化器状态）。</li></ul><h3 id="训练机制" tabindex="-1">训练机制 <a class="header-anchor" href="#训练机制" aria-label="Permalink to &quot;训练机制&quot;">​</a></h3><ul><li><strong>损失函数 / 交叉熵（Cross-entropy）</strong>：衡量预测分布离真实下一个 token 有多远。<code>loss = -log P(正确token)</code>。<strong>数字直觉</strong>：随机猜的 loss ≈ <code>ln(vocab)</code> ≈ 11.7（词表 128k）；训好的模型在 2 以下。</li><li><strong>梯度 / 反向传播（Backpropagation）</strong>：对 loss 求每个权重的偏导，得到&quot;往哪调、调多少&quot;，从输出层逐层回传。<strong>没有残差流（<a href="#_2-主干-残差流">§2</a>）的恒等短路，这个回传在几十层深度上就会消失。</strong></li></ul><h3 id="_1-预训练-pretraining-——最贵的一步" tabindex="-1">① 预训练（Pretraining）——最贵的一步 <a class="header-anchor" href="#_1-预训练-pretraining-——最贵的一步" aria-label="Permalink to &quot;① 预训练（Pretraining）——最贵的一步&quot;">​</a></h3><ul><li><strong>数据</strong>：万亿级 token 的无标注文本（网页 / 书 / 代码）。<strong>数据质量是这一步的全部</strong>——去重、过滤、配比比架构调参重要得多。</li><li><strong>任务</strong>：自监督&quot;预测下一个词&quot;。没有人工标注，文本自己当标签。</li><li><strong>产出</strong>：<strong>基座模型（Base / Pretrained Model）</strong>——只会<strong>续写</strong>。你问它&quot;法国首都是哪&quot;，它可能续一句&quot;？德国首都是哪？意大利首都是哪？&quot;，因为在互联网语料里这才是常见的接下去写法。它不是不知道答案，是不知道你在提问。</li></ul><h3 id="_2-监督微调-sft" tabindex="-1">② 监督微调（SFT） <a class="header-anchor" href="#_2-监督微调-sft" aria-label="Permalink to &quot;② 监督微调（SFT）&quot;">​</a></h3><ul><li><strong>数据</strong>：人工写的（指令，理想回答）对。<strong>量少质精</strong>——通常几万到几十万条，不是几亿。</li><li><strong>产出</strong>：<strong>指令微调模型（Instruct Model）</strong>。base 和 instruct 的分水岭就在这。<strong>它主要学的是&quot;格式和角色&quot;，不是新知识</strong>——知识在预训练里就装完了。</li><li><strong>附带效应</strong>：这一步引入了 <strong>chat template</strong>（<code>&lt;|im_start|&gt;user</code> 之类的特殊 token）。用错模板，instruct 模型表现会断崖下跌，这是本地部署最常见的坑。</li></ul><h3 id="_3-偏好对齐-rlhf-dpo" tabindex="-1">③ 偏好对齐（RLHF / DPO） <a class="header-anchor" href="#_3-偏好对齐-rlhf-dpo" aria-label="Permalink to &quot;③ 偏好对齐（RLHF / DPO）&quot;">​</a></h3><ul><li><strong>数据</strong>：人类对&quot;哪个回答更好&quot;的成对比较。</li><li><strong>做法</strong>：<strong>RLHF</strong> 先训一个奖励模型打分，再用 PPO 让策略往高分走；<strong>DPO</strong> 跳过奖励模型和 RL 循环，直接在偏好对上做优化。</li><li><strong>目标</strong>：有用、无害、诚实。</li><li><strong>⚠️ 别再写&quot;DPO 现在更主流&quot;</strong>：2024 年是对的（Llama 3 就是 DPO 的高点，论文明确说 DPO 比 PPO 省算力且效果更好）。<strong>R1 之后翻过去了</strong>——DeepSeek V3 论文里 &quot;DPO&quot; 出现 <strong>0 次</strong>，用 GRPO；Qwen3 也是 <strong>0 次</strong>，用 GRPO 后来换 GSPO；Llama 4 把 DPO 降级成最后一道轻量抛光，并明确说&quot;<strong>SFT 和 DPO 会过度约束模型，限制 online RL 阶段的探索</strong>&quot;。DPO 在 2026 年的准确定位：<strong>小规模社区微调的便宜稳定选项 + 最后的轻量打磨</strong>，不是前沿主线。轨迹是 <code>PPO/RLHF (2022) → DPO (2023-24) → GRPO/RLVR (2025-26)</code>。</li></ul><h3 id="_4-推理训练-rlvr-rl-with-verifiable-rewards" tabindex="-1">④ 推理训练（RLVR：RL with Verifiable Rewards） <a class="header-anchor" href="#_4-推理训练-rlvr-rl-with-verifiable-rewards" aria-label="Permalink to &quot;④ 推理训练（RLVR：RL with Verifiable Rewards）&quot;">​</a></h3><ul><li><strong>数据</strong>：能自动判对错的题——数学、代码、单元测试。<strong>&quot;可验证&quot;是关键词</strong>：奖励来自编译器和测试，不来自人类打分，所以能无限扩展。</li><li><strong>做法</strong>：用 <strong>GRPO</strong> 及其后继（GSPO、DAPO）奖励正确答案，长链思考是被逼出来的副产品，不是被教的。</li><li><strong>产出</strong>：推理模型（o1/o3、DeepSeek-R1、Qwen3 thinking）。R1-Zero 最惊人的地方是<strong>纯 RL、不做 SFT</strong> 就涌现出了反思和自我纠错。</li><li><strong>和 CoT 的关系</strong>：CoT（<a href="#_9-不在本文范围">§9</a>）原本是<strong>提示技巧</strong>——你要求模型一步步想。RLVR 之后它变成了<strong>训练进权重的行为</strong>——模型自己就会想，不需要你提示。</li></ul><h3 id="附-蒸馏-distillation" tabindex="-1">附：蒸馏（Distillation） <a class="header-anchor" href="#附-蒸馏-distillation" aria-label="Permalink to &quot;附：蒸馏（Distillation）&quot;">​</a></h3><ul><li><strong>是什么</strong>：两种不同的东西，别混： <ol><li><strong>经典 logit 蒸馏</strong>：学生模型拟合教师的完整输出分布（软标签），比拟合硬标签信息量大。<code>distilgpt2</code>、<code>DistilBERT</code> 是这一类。</li><li><strong>&quot;R1-distill&quot; 式</strong>：拿大模型生成的<strong>推理轨迹</strong>去做学生的 SFT。本质是 SFT，只是数据由模型产出。今天说&quot;蒸馏&quot;多半指这个。</li></ol></li><li><strong>没有它会坏在哪</strong>：小模型直接从原始数据训，效果远不如从大模型的输出学。这也是 2025 年后小模型能力猛涨的主因——<strong>它们不是学得更好，是有了更好的老师。</strong></li></ul><h3 id="各类模型走到了哪一步" tabindex="-1">各类模型走到了哪一步 <a class="header-anchor" href="#各类模型走到了哪一步" aria-label="Permalink to &quot;各类模型走到了哪一步&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>走过的阶段</th><th>行为特征</th></tr></thead><tbody><tr><td><code>distilgpt2</code></td><td>① 预训练 + 蒸馏</td><td>只会续写，不听指令</td></tr><tr><td><code>Llama-3-8B</code>（base）</td><td>①</td><td>同上</td></tr><tr><td><code>Qwen3-0.5B-Instruct</code></td><td>① → ② → ③</td><td>能听懂并回答问题</td></tr><tr><td><code>DeepSeek-R1</code></td><td>① → ② → ③ → ④</td><td>先输出长思考链再答</td></tr></tbody></table><hr><h2 id="_8-硬件账本" tabindex="-1">8. 硬件账本 <a class="header-anchor" href="#_8-硬件账本" aria-label="Permalink to &quot;8. 硬件账本&quot;">​</a></h2><blockquote><p>顺序很重要：硬件放在软件链<strong>之后</strong>。它是前面那条链的<strong>后果</strong>，不是原因。</p></blockquote><h3 id="gpu" tabindex="-1">GPU <a class="header-anchor" href="#gpu" aria-label="Permalink to &quot;GPU&quot;">​</a></h3><ul><li><strong>是什么</strong>：海量核心的并行处理器。LLM 的前向几乎全是大矩阵乘。CPU 核少但单核快、擅长串行分支；GPU 核多且规整、擅长并行数值计算。</li><li><strong>数字</strong>：H100 的 bf16 算力约 <strong>1000 TFLOPS</strong>（稀疏），HBM 带宽约 <strong>3.35 TB/s</strong>。记住这两个数的比例。</li></ul><h3 id="hbm-高带宽显存" tabindex="-1">HBM（高带宽显存） <a class="header-anchor" href="#hbm-高带宽显存" aria-label="Permalink to &quot;HBM（高带宽显存）&quot;">​</a></h3><ul><li><strong>是什么</strong>：堆叠在 GPU 芯片旁的高速显存。带宽极高，<strong>容量有限</strong>（H100 是 80 GB）。权重、激活、KV Cache 全住在这里。</li><li><strong>数字</strong>：一张显存预算表（70B，bf16）：<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>权重          70B × 2 B  = 140 GB   ← 已经超过单张 H100 的 80 GB</span></span>
<span class="line"><span>KV Cache @128k          =  42.9 GB  ← 见 §6</span></span>
<span class="line"><span>激活值 + 碎片            ≈  几 GB</span></span>
<span class="line"><span>────────────────────────────────────</span></span>
<span class="line"><span>合计                    ≈ 185 GB    → 至少 3~4 张卡</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div></li><li><strong>为什么&quot;带宽&quot;比&quot;算力&quot;更常成为瓶颈</strong>：decode 阶段每生成 <strong>1 个</strong> token，要把<strong>全部权重</strong>从 HBM 读进计算单元一遍。70B bf16 = 140 GB，除以 3.35 TB/s → <strong>理论上限约 24 token/s（batch=1）</strong>，跟算力毫无关系。<strong>这就是 decode 是 memory-bound 的意思</strong>，也是为什么提高 batch size 几乎免费提升总吞吐：读一次权重，服务多个请求。</li></ul><h3 id="量化-quantization" tabindex="-1">量化（Quantization） <a class="header-anchor" href="#量化-quantization" aria-label="Permalink to &quot;量化（Quantization）&quot;">​</a></h3><ul><li><strong>是什么</strong>：用更少的位表示权重（和可选的激活/KV Cache）。<strong>⚠️ 起点是 bf16，不是 fp32</strong>——早就没人用 fp32 做推理了，DeepSeek V3 甚至原生 FP8 训练。</li><li><strong>数字</strong>：70B 的体积：<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>bf16  →  140 GB   （2 张 80G 卡）</span></span>
<span class="line"><span>fp8   →   70 GB   （1 张，刚好）</span></span>
<span class="line"><span>int4  →   35 GB   （1 张，宽裕；常见质量损失 1~3%）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div>常见方案名：GPTQ、AWQ、GGUF（llama.cpp）。</li><li><strong>没有它会坏在哪</strong>：70B 在单卡上根本跑不起来。而且量化不只省容量——<strong>它同时减少要搬的字节数，所以直接提升 decode 速度</strong>（回到上面那个带宽账）。这是&quot;省显存&quot;之外更容易被忽略的收益。</li></ul><h3 id="三者关系链" tabindex="-1">三者关系链 <a class="header-anchor" href="#三者关系链" aria-label="Permalink to &quot;三者关系链&quot;">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>                  算力(FLOPS)  ← prefill 卡在这里</span></span>
<span class="line"><span>                       ▲</span></span>
<span class="line"><span>   ┌───────────────────┴───────────────────┐</span></span>
<span class="line"><span>   │      GPU 计算单元：矩阵乘(权重 × 激活)   │</span></span>
<span class="line"><span>   └───────────────────┬───────────────────┘</span></span>
<span class="line"><span>                       ▲</span></span>
<span class="line"><span>              每步都要把权重整个读一遍</span></span>
<span class="line"><span>              带宽 3.35 TB/s  ← decode 卡在这里</span></span>
<span class="line"><span>                       ▲</span></span>
<span class="line"><span>   ┌───────────────────┴───────────────────┐</span></span>
<span class="line"><span>   │  HBM 80 GB：权重 + 激活 + KV Cache     │</span></span>
<span class="line"><span>   └───────────────────┬───────────────────┘</span></span>
<span class="line"><span>                       ▲</span></span>
<span class="line"><span>              KV Cache 随上下文线性膨胀，挤占容量</span></span>
<span class="line"><span>              （GQA / MLA / 滑动窗口 就是压这一项，见 §3）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>一句话：<strong>prefill 拼算力，decode 拼带宽；容量决定&quot;装不装得下&quot;，带宽决定&quot;跑多快&quot;。上下文长度由训练决定，能不能负担得起由 HBM 决定。</strong></p><hr><h2 id="_9-不在本文范围" tabindex="-1">9. 不在本文范围 <a class="header-anchor" href="#_9-不在本文范围" aria-label="Permalink to &quot;9. 不在本文范围&quot;">​</a></h2><p>下面这些不属于&quot;一次前向传播&quot;这条链，硬塞进来只会让文档退回成词汇表。它们各自应该是独立的一篇：</p><h3 id="已经写了的" tabindex="-1">已经写了的 <a class="header-anchor" href="#已经写了的" aria-label="Permalink to &quot;已经写了的&quot;">​</a></h3><ul><li><strong>应用层</strong> → <a href="/blog/ai/agent/agent-loop.html">Agent：跟着一次循环走完全程</a> Agent / Function Calling / RAG / MCP / 上下文工程。主轴是那个只增不减的 <code>ctx</code> 数组。思想原型见 <a href="/blog/ai/agent/yao-2023-react.html">ReAct 论文笔记</a>。</li><li><strong>多模态</strong> → <a href="/blog/ai/llm-basics/multimodal.html">多模态：一张图怎么变成 token</a> ViT / CLIP / SigLIP / 投影层 / 图像计费 / 原生多模态。主轴是 <code>N</code>——一张图变成多少个 token。</li><li><strong>训练系统</strong> → <a href="/blog/ai/llm-basics/distributed.html">一张卡装不下之后：把模型切开</a> DP / TP / PP / CP / EP、ZeRO、FlashAttention、MFU。从 <a href="#_8-硬件账本">§8</a> 那张 185 GB 的账单往下接。</li></ul><h3 id="还没写的" tabindex="-1">还没写的 <a class="header-anchor" href="#还没写的" aria-label="Permalink to &quot;还没写的&quot;">​</a></h3><ul><li><strong>提示技巧</strong>：Prompt Engineering、CoT、few-shot、ReAct ⚠️ 但注意 <a href="#_4-推理训练-rlvr-rl-with-verifiable-rewards">§7④</a>——CoT 已经从提示技巧变成了训进权重的行为。这一篇真要写，主轴应该是<strong>时间线</strong>（《哪些提示技巧被训进了权重》），而不是技巧清单。</li><li><strong>安全</strong>：提示注入、越狱、护栏、对齐税 最好的切入点是把攻击点标在 <a href="#_0-骨架">§0</a> 那张骨架图上。提示注入之所以无法用 prompt 修复，是因为&quot;指令&quot;和&quot;数据&quot;进的是同一张 embedding 表——<strong>模型在架构层面就分不开</strong>。</li><li><strong>评测</strong>：MMLU / GPQA / SWE-bench、污染问题、LLM-as-judge 固定格式该是「测什么 / 满分多少、蒙分基线多少 / 怎么被刷」。MMLU 四选一的蒙分基线是 25%，这个数一放，一半的榜单叙事就自己塌了。</li><li><strong>模型选型</strong>：开源 vs 闭源、许可证、API 定价 <strong>这个不该写成文章</strong>——价格三个月变一次，写死就是负债。它该是一张定期更新的表加一个成本函数，而成本函数的料在 <a href="#_1-入口-从文本到向量">§1</a>（token 换算）、<a href="#_8-硬件账本">§8</a>（显存账）和 <a href="/blog/ai/agent/agent-loop.html#_1-开工前-工具定义的固定成本">agent-loop §1</a>（上下文预算）里已经齐了。</li></ul><hr>`,104)])])}const u=o(e,[["render",r]]);export{h as __pageData,u as default};
